import{_ as a,a0 as s,w as r,s as u,ao as d,I as n,x as e,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Spotify 原生Linux客户端更新，暗黑風格來襲 | LCTT x X-CMD","titleTemplate":false,"description":"Spotify 原生Linux客户端更新，暗黑風格來襲 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Spotify 原生Linux客户端更新，暗黑風格來襲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Spotify 原生Linux客户端更新，暗黑風格來襲 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Native Spotify for Linux Client Updated With New Dark Design","title":"Spotify 原生Linux客户端更新，暗黑風格來襲","tag":"201405","desc":""},"relativePath":"201405/Native Spotify for Linux Client Updated With New Dark Design.md","filePath":"[post].md"}'),f={name:"201405/Native Spotify for Linux Client Updated With New Dark Design.md"};function l(y,t,m,x,g,S){const p=s("Link");return r(),u("div",null,[t[11]||(t[11]=d(`<h1 id="spotify-原生linux客户端更新-暗黑風格來襲" tabindex="-1">Spotify 原生Linux客户端更新，暗黑風格來襲 <a class="header-anchor" href="#spotify-原生linux客户端更新-暗黑風格來襲" aria-label="Permalink to “Spotify 原生Linux客户端更新，暗黑風格來襲”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/05/spotify.jpg" alt=""></p><p><strong>繼streaming service上個月在其它平台上發佈它的應用之後，以同樣的扁平化和黑色風格的設計，Linux版本的Spotify客户端也發佈了更新。</strong></p><p>金屬質感的灰色元素和白色清爽的條區設計形成了基於黑色的風格，以黑色和淺黑色的顏色為主。甚至公司的綠色的商標也不能倖免，以奇怪的顏色出現在各種地方。</p><p>在作曲家和個人資料條目中圖片的設計上均採用了圓形的設計元素，並且在導航欄和播放控制按鈕的地方採用了iOS 7風格。</p><p>Spotify官方説道這種設計風格突出了軟件的內容，他們將之比作“<em>熄掉所有燈光的劇場。</em>”</p><p>除了吸引你眼球的這些改變，還有一些你可能錯過的不易察覺的變化。這包括Open SSL 1.0.x的使用、使用<em>libavcodec54</em>來實現本地音樂重放以及播放曲目變化時對本地系統通知的調用支持。</p><p>現在，該軟件已不再提供32位的版本。</p><p>由於長期處於預覽階段，Linux下的原生Spotify客户端<strong>支持免費和訂閲賬户</strong>。</p><h3 id="安裝spotify" tabindex="-1">安裝Spotify <a class="header-anchor" href="#安裝spotify" aria-label="Permalink to “安裝Spotify”">​</a></h3><p>要在Ubuntu 14.04 LTS上安裝Spotify，你可以打開終端，然後輸入下面的命令。</p><p>首先將Spotify官方的軟件倉庫添加到你的軟件源列表中：</p><pre><code>sudo sh -c &#39;echo &quot;deb http://repository.spotify.com stable non-free&quot; &gt; /etc/apt/sources.list.d/spotify.list&#39;
</code></pre><p>添加該軟件倉庫的安全密鑰來避免不必要的錯誤：</p><pre><code>sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys 94558F59
</code></pre><p>最後，更新並且安裝Spotify：</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install spotify-client-qt
</code></pre><p>安裝完成後就可以從Dash啓動Spotify了。</p><hr>`,19)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),i(p,{href:"http://www.omgubuntu.co.uk/2014/05/spotify-linux-preview-update-new-design"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.omgubuntu.co.uk/2014/05/spotify-linux-preview-update-new-design",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=e("譯者：",-1)),i(p,{href:"https://github.com/JonathanKang"},{default:o(()=>[...t[2]||(t[2]=[e("JonathanKang",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),i(p,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),i(p,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const C=a(f,[["render",l]]);export{w as __pageData,C as default};
